def is_valid(p, c):
    """Check if a single observation is valid"""
    return c <= p


def is_sequence_valid(p_list, c_list):
    """Check if a sequence of observations is valid"""
    # Check if each observation is valid
    for p, c in zip(p_list, c_list):
        if not is_valid(p, c):
            return False

    # Check if plays and clears never decrease
    for i in range(len(p_list) - 1):
        if p_list[i+1] < p_list[i] or c_list[i+1] < c_list[i]:
            return False

    # Check if increases are consistent
    for i in range(len(p_list) - 1):
        play_increase = p_list[i+1] - p_list[i]
        clear_increase = c_list[i+1] - c_list[i]
        if clear_increase > play_increase:
            return False

    return True

T = int(input())
for _ in range(T):
    n = int(input())
    p_list = []
    c_list = []
    for _ in range(n):
        p, c = map(int, input().split())
        p_list.append(p)
        c_list.append(c)

    if is_sequence_valid(p_list, c_list):
        print("YES")
    else:
        print("NO")
"}

