def find_lexicographically_max_subsequence(s):
    """Find the lexicographically maximum subsequence of string s."""
    result = []

    for char in s:
        # If the current character is larger than the last character in result,
        # we should remove the last character to make room for a larger one
        while result and char > result[-1]:
            result.pop()
        result.append(char)

    return ''.join(result)

