def count_medians(coords):
    coords.sort()
    n = len(coords)
    if n % 2 == 1:
        # odd: only one median
        return {coords[n // 2]}
    else:
        # even: any value between the two middle values (inclusive)
        left = coords[n // 2 - 1]
        right = coords[n // 2]
        return set(range(left, right + 1))

t = int(input())
for _ in range(t):
    n = int(input())
    x_coords = []
    y_coords = []
    for _ in range(n):
        x, y = map(int, input().split())
        x_coords.append(x)
        y_coords.append(y)

    medians_x = count_medians(x_coords)
    medians_y = count_medians(y_coords)

    print(len(medians_x) * len(medians_y))
"}

