def solve():
    t = int(input())
    for _ in range(t):
        s = input().strip()
        n = len(s)

        # dp[i][j] = True if it's possible to reach balance j after i characters
        dp = [[False] * (n + 1) for _ in range(n + 1)]
        dp[0][0] = True

        for i in range(n):
            for j in range(n + 1):
                if dp[i][j]:
                    if s[i] == '(' or s[i] == '?':
                        # Treat as '('
                        dp[i + 1][j + 1] = True
                    if s[i] == ')' or s[i] == '?':
                        # Treat as ')'
                        if j > 0:
                            dp[i + 1][j - 1] = True

        if dp[n][0]:
            print("YES")
        else:
            print("NO")

solve()
