line = sys.stdin.readline().strip()
length = len(line)

if length % 2 == 0:
    # Even length: need at least two identical characters
    # and middle two characters should be different from each other and both ends
    count = {}
    for ch in line:
        count[ch] = count.get(ch, 0) + 1

    # Check if any character appears at least twice
    at_least_two = any(v >= 2 for v in count.values())

    # Check middle two characters
    mid1 = line[length//2 - 1]
    mid2 = line[length//2]
    # Middle two should be different from each other
    mid1_diff = mid1 != mid2
    # Middle two should be different from both ends
    mid1_ends_diff = mid1 != line[0] and mid1 != line[-1]
    mid2_ends_diff = mid2 != line[0] and mid2 != line[-1]

    if at_least_two and mid1_diff and mid1_ends_diff and mid2_ends_diff:
        print("YES")
    else:
        print("NO")
else:
    # Odd length: need at least two identical characters
    count = {}
    for ch in line:
        count[ch] = count.get(ch, 0) + 1

    if any(v >= 2 for v in count.values()):
        print("YES")
