    for _ in range(t):
        s = input().strip()

        # Check if we have exactly one '(' and one ')'
        if s.count('(') != 1 or s.count(')') != 1:
            print("NO")
            continue

        # Track minimum and maximum number of '(' at each position
        min_open = 1
        max_open = 1

        for c in s:
            if c == '(':
                min_open += 1
                max_open += 1
            elif c == ')':
                min_open -= 1
                max_open -= 1
            else:  # c == '?':
                min_open += 1
                max_open -= 1

            # If at any point min > max, it's impossible
            if min_open > max_open:
                print("NO")
                break
        else:
            # If we didn't break, check if we have exactly one of each
            print("YES")

