import sys
import heapq

def dijkstra(n, adj, start):
    INF = float('inf')
    dist = [INF] * (n + 1)
    dist[start] = 0
    heap = [(0, start)]

    while heap:
        cost, u = heapq.heappop(heap)
        if cost > dist[u]:
            continue

        for v in adj[u]:
            # Go from u to v through any intermediate node a
            # The minimum cost from u to v is min over all a of (w_ua + w_av)^2
            min_cost = INF
            for a in adj[u]:
                if a == v:
                    continue
                if v in adj[a]:
                    min_cost = min(min_cost, (adj[u][a] + adj[a][v])**2)

            if min_cost < dist[v]:
                dist[v] = min_cost
                heapq.heappush(heap, (dist[v], v))

    return dist

# Read input
