import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    k = int(next(it))
    x = int(next(it))
    a = [int(next(it)) for _ in range(n)]

    best_vals = a.copy()
    ops_used = 0

    import heapq

    pos_heap = []
    neg_heap = []

    for i, ai in enumerate(best_vals):
        if ai > 0:
            heapq.heappush(pos_heap, (-(ai + x) / ai, i))
        elif ai < 0:
            heapq.heappush(neg_heap, (-(ai - x) / ai, i))

    for _ in range(k):
        if not pos_heap and not neg_heap:
            break

        if not neg_heap:
            impact, i = heapq.heappop(pos_heap)
            best_vals[i] += x
        elif not pos_heap:
            impact, i = heapq.heappop(neg_heap)
            best_vals[i] -= x
        else:
            if pos_heap[0][0] > neg_heap[0][0]:
                impact, i = heapq.heappop(pos_heap)
                best_vals[i] += x
            else:
                impact, i = heapq.heappop(neg_heap)
                best_vals[i] -= x

        ops_used += 1

    print(' '.join(map(str, best_vals)))

if __name__ == '__main__':
