import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    out_lines = []

    for _ in range(t):
        n = int(next(it))
        m = int(next(it))

        a = []
        for _ in range(n):
            row = [int(next(it)) for _ in range(m)]
            a.append(row)

        # Process the matrix
        for i in range(n):
            for j in range(m):
                # Check left neighbor (same row, previous column)
                if j > 0 and a[i][j] == a[i][j-1]:
                    a[i][j] += 1

                # Check top neighbor (previous row, same column)
                if i > 0 and a[i][j] == a[i-1][j]:
                    a[i][j] += 1

        # Output the result
        for row in a:
            out_lines.append(" ".join(map(str, row)))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
