import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # Parse input
    n = int(data[0])
    a = int(data[1])
    b = int(data[2])
    k = int(data[3])
    s = data[4]

    # Find all intervals where a ship could be placed
    intervals = []
    start = None

    for i in range(n):
        if s[i] == '0':
            if start is None:
                start = i + 1  # 1-indexed
        else:
            if start is not None:
                # This run of 0's ends at i-1
                length = i - start + 1
                if length >= b:
                    # Add all possible ship placements in this run
                    for s_pos in range(start, start + length - b + 1):
                        intervals.append((s_pos, s_pos + b - 1))
                start = None

    # If we ended with a run of 0's
    if start is not None:
        length = n - start + 1
        if length >= b:
            for s_pos in range(start, start + length - b + 1):
                intervals.append((s_pos, s_pos + b - 1))

    # Greedy algorithm to cover intervals
    selected = []
    i = 0

    while i < len(intervals):
        # Select the rightmost point of this interval
        point = intervals[i][1]
        selected.append(point)

        # Skip all intervals that include this point
        j = i + 1
        while j < len(intervals) and intervals[j][0] <= point:
            j += 1
        i = j

    print(len(selected))
    print(' '.join(map(str, selected)))

if __name__ == '__main__':
    solve()
