# States: 0 (nothing matched), 1 (h), 2 (ha), 3 (har)
dp = [float('inf')] * 4
# dp[0] = 0 (no characters matched yet)
dp[0] = 0

for i in range(n):
    new_dp = dp[:]  # Option: remove current character

    # Option: keep current character
    for state in range(4):
        if state == 0:
            if s[i] == 'h':
                # We can either keep this h and go to state 1
                new_dp[1] = min(new_dp[1], dp[state] + a[i])
                # Or we could consider this h as part of a later sequence
                # But we can't go to state 0 if we keep it
                pass
        elif state == 1:
            if s[i] == 'a':
                new_dp[2] = min(new_dp[2], dp[state] + a[i])
            elif s[i] == 'h':
                # We have an 'h' already, but we could remove the previous 'h'
                # and keep this 'h' as the new starting point
                new_dp[0] = min(new_dp[0], dp[state] + a[i])
        elif state == 2:
            if s[i] == 'r':
                new_dp[3] = min(new_dp[3], dp[state] + a[i])
        elif state == 3:
            if s[i] == 'd':
                # This would complete 'hard', we must remove it
                pass
            elif s[i] == 'h':
                # We could consider this as a new starting point
                new_dp[0] = min(new_dp[0], dp[state] + a[i])
            elif s[i] == 'a':
                # After 'har', we could try to match 'a' again
                # But 'a' comes after 'h', not before, so we reset to state 0
                new_dp[0] = min(new_dp[0], dp[state] + a[i])

    dp = new_dp

print(min(dp))
