import sys
from collections import deque, defaultdict

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    edges = [[] for _ in range(n + 1)]
    for _ in range(m):
        a = int(next(it))
        b = int(next(it))
        c = int(next(it))
        edges[a].append((b, c))
        edges[b].append((a, c))

    # For each node, store its value
    values = [None] * (n + 1)

    # BFS/DFS to assign values
    for start in range(1, n + 1):
        if values[start] is None:
            # Start with value 0
            values[start] = 0

            # BFS queue
            queue = deque([start])

            while queue:
                u = queue.popleft()

                for v, color in edges[u]:
                    if values[v] is None:
                        # Propagate value from u to v
                        if color == 1:
                            # x_u + x_v = 1 => x_v = 1 - x_u
                            values[v] = 1 - values[u]
                        else:
                            # x_u + x_v = 2 => x_v = 2 - x_u
                            values[v] = 2 - values[u]
                        queue.append(v)
                    else:
                        # Check constraint
                        if color == 1 and abs(values[u] + values[v] - 1) > 1e-10:
                            print("NO")
                            return
                        if color == 2 and abs(values[u] + values[v] - 2) > 1e-10:
                            print("NO")
                            return

    # Check if all constraints are satisfied
    for a in range(1, n + 1):
        for b, c in edges[a]:
            if a < b:  # Avoid double checking
                if c == 1 and abs(values[a] + values[b] - 1) > 1e-10:
                    print("NO")
                    return
                if c == 2 and abs(values[a] + values[b] - 2) > 1e-10:
                    print("NO")
                    return

    print("YES")

    # Output values (convert to float for formatting)
    output = [str(float(values[i])) for i in range(1, n + 1)]
    print(" ".join(output))

if __name__ == "__main__":
    solve()
