prefix = [[0] * (n + 1) for _ in range(n + 1)]
for i in range(1, n + 1):
    for j in range(1, n + 1):
        prefix[i][j] = prefix[i-1][j] + prefix[i][j-1] - prefix[i-1][j-1] + u[i-1][j-1]

# Function to compute cost of gondola from a to b (1-indexed)
def cost(a, b):
    """Returns the sum of u[i][j] for all i, j in [a, b] where i < j"""
    total = 0
    for i in range(a, b + 1):
        for j in range(i + 1, b + 1):
            total += u[i - 1][j - 1]
    return total

# Dynamic programming solution
INF = float('inf')
dp = [[INF] * (k + 1) for _ in range(n + 1)]
