import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        m = int(next(it))
        a = []
        for _ in range(n):
            row = [int(next(it)) for _ in range(m)]
            a.append(row)

        # Create the solution matrix b
        b = [[0]*m for _ in range(n)]

        # First pass: check above
        for i in range(n):
            for j in range(m):
                if i > 0 and a[i][j] == a[i-1][j]:
                    b[i][j] = a[i][j] + 1
                else:
                    b[i][j] = a[i][j]

        # Second pass: check left
        for i in range(n):
            for j in range(1, m):
                if b[i][j] == b[i][j-1]:
                    b[i][j] += 1

        # Output
        for row in b:
            print(' '.join(map(str, row)))

if __name__ == "__main__":
    solve()
