def solve():
    # Read input
    n, v = map(int, input().split())
    vehicles = []
    for i in range(n):
        t, p = map(int, input().split())
        vehicles.append((t, p))

    # Initialize DP: dp[s] = maximum carrying capacity using exactly s space
    # And also track which vehicles were used to reach that capacity
    dp = {0: []}  # dp[s] = (max capacity, list of vehicle indices)

    # Process each vehicle
    for i, (t, p) in enumerate(vehicles):
        # We need to create a new temporary dictionary to avoid overwriting
        temp = {}

        # Try not taking this vehicle
        for space in dp:
            if space not in temp:
                temp[space] = dp[space]

        # Try taking this vehicle
        for space in dp:
            new_space = space + t
            if new_space <= v:
                new_capacity = dp[space][0] + p
                new_indices = dp[space][1] + [i + 1]

                if new_space not in temp:
                    temp[new_space] = (new_capacity, new_indices)
                else:
                    current_capacity, current_indices = temp[new_space]
                    if new_capacity > current_capacity or (new_capacity == current_capacity and sorted(new_indices) < sorted(current_indices)):
                        temp[new_space] = (new_capacity, new_indices)

        # Update dp
        dp = temp

    # Find the maximum capacity
    max_capacity = max(dp.values(), key=lambda x: x[0])[0]

    # Find any configuration that achieves max capacity
    for space in dp:
        if dp[space][0] == max_capacity:
            result = sorted(dp[space][1])
            break

    # Output
    print(max_capacity)
    print(' '.join(map(str, result)))

