def find_cycles(n, p):
    visited = [False] * (n + 1)
    cycles = []

    for i in range(1, n + 1):
        if not visited[i]:
            cycle = []
            j = i
            while not visited[j]:
                visited[j] = True
                cycle.append(j)
                j = p[j - 1]  # Adjust for 0-indexed list
            cycles.append(cycle)

    return cycles

n = int(input())
perm = list(map(int, input().split()))

# Find cycles in the permutation
cycles = find_cycles(n, perm)
m = len(cycles)

# Build the result
edges = []

# For each cycle, add edges for the chain
for cycle in cycles:
    k = len(cycle)
    if k > 1:
        # Connect vertices in the order they appear in the cycle
        for i in range(k - 1):
            edges.append((cycle[i], cycle[i + 1]))

# Connect all cycles together in a linear fashion
if m > 1:
    for i in range(m - 1):
        # Connect last vertex of current cycle to first vertex of next cycle
        edges.append((cycles[i][-1], cycles[i+1][0]))

# Check if the tree is invariant
# For each edge (u, v), check if (p[u-1], p[v-1]) is also an edge
is_invariant = True
edge_set = set()
for u, v in edges:
    edge_set.add((u, v))
    edge_set.add((v, u))

for u, v in edges:
    pu = perm[u - 1]
    pv = perm[v - 1]
    if (pu, pv) not in edge_set:
        is_invariant = False
        break

if is_invariant:
    print("YES")
    for u, v in edges:
        print(u, v)
else:
    print("NO")
