    INF = 10**18
    dp = [[INF] * 2 for _ in range(m + 1)]
    dp[0][0] = 0  # Starting at column 0 with no color

    for col in range(m):
        color = grid[0][col]
        # Try to continue the current stripe
        for c in range(2):
            if dp[col+1][c] > dp[col][c]:
                dp[col+1][c] = dp[col][c]
        # Try to start a new stripe with color col
        for c in range(2):
            if color == ('#' if c == 1 else '.'):  # match the color
                if dp[col+1][c] > dp[col][0]:
                    dp[col+1][c] = dp[col][0]

