    return (r // d) - ((l - 1) // d)

# Find the divisor that appears most frequently
max_count = 0
best_divisor = l  # Start with l as a candidate

# Special case: if l == r, the answer is l itself
if l == r:
    print(l)
else:
    # Iterate through possible divisors
    # The count decreases with d, so we just need to consider relatively small d
    for d in range(2, min(r, 1000000) + 1):
        cnt = count_multiples(d)
        if cnt > max_count:
            max_count = cnt
            best_divisor = d
    print(best_divisor)

