def solve():
    n, m, x, y = map(int, input().split())
    grid = [input().strip() for _ in range(n)]

    # Count black and white pixels per column
    col_black = [0] * m
    col_white = [0] * m
    for j in range(m):
        for i in range(n):
            if grid[i][j] == '#':
                col_black[j] += 1
            else:
                col_white[j] += 1

    # dp[i][color] = minimum cost to paint first i columns with last color being 'color'
    dp = [[float('inf')] * 2 for _ in range(m + 1)]
    dp[0][0] = 0  # 0 columns, last color black (sentinel value)
    dp[0][1] = 0  # 0 columns, last color white

    for i in range(1, m + 1):
        # Try all possible widths for the strip ending at column i
        for width in range(1, y + 1):
            if i - width < 0:
                continue

            # Cost to paint columns [i-width, i-1] with a specific color
            cost_black = sum(col_white[j] for j in range(i - width, i))
            cost_white = sum(col_black[j] for j in range(i - width, i))

            # Try both possible colors for this strip
            for last_color in range(2):
                # Try both possible colors for the previous strip
                for prev_color in range(2):
                    # Only update if the previous strip's color is different
                    # Because consecutive same-color strips are not allowed
                    if last_color == prev_color:
                        continue

                    dp[i][last_color] = min(
                        dp[i][last_color],
                        dp[i - width][prev_color] + (cost_black if last_color == 0 else cost_white)
                    )

    print(min(dp[m][0], dp[m][1]))

solve()
