def solve() -> None:
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return

    # Parse input
    n, m = map(int, data[0].split())
    s = data[1]

    # Track which positions are removed
    removed = [False] * n

    # Process operations
    for i in range(2, 2 + m):
        if i >= len(data):
            break
        parts = data[i].split()
        l = int(parts[0]) - 1  # Convert to 0-indexed
        r = int(parts[1]) - 1
        c = parts[2]

        # Mark positions with character c in range [l, r] as removed
        for pos in range(l, r + 1):
            if s[pos] == c:
                removed[pos] = True

    # Build result
    result = []
    for i in range(n):
        if not removed[i]:
            result.append(s[i])

    sys.stdout.write(''.join(result))

if __name__ == '__main__':
    solve()
