def modinv(a, m=998244353):
    """Return modular inverse of a mod m using Fermat's little theorem."""
    return pow(a, m - 2, m)

n = int(input())

# Count how many kids want each item
item_counts = {}

# Read each kid's list of items
for _ in range(n):
    parts = list(map(int, input().split()))
    k = parts[0]
    items = parts[1:]

    # Update item counts
    for item in items:
        if item not in item_counts:
            item_counts[item] = 0
        item_counts[item] += 1

    # Add to total sum
    inv_k = modinv(k)
    for item in items:
        item_counts[item] = (item_counts[item] * inv_k) % 998244353

# Calculate final answer
ans = 0
for count in item_counts.values():
    ans = (ans + count) % 998244353

inv_n2 = modinv(n) * modinv(n) % 998244353
ans = (ans * inv_n2) % 998244353

print(ans)
