    for i in range(n):
        wi = int(next(it))
        hi = int(next(it))
        if wi > w_card and hi > h_card:
            envelopes.append((wi, hi, i + 1))  # (width, height, 1-indexed index)

    if not envelopes:
        print(0)
        return

    # Sort by width, then by height
    envelopes.sort(key=lambda x: (x[0], x[1]))

    # dp[i] = (max_length, last_index, last_height)
    dp = []

    for wi, hi, idx in envelopes:
        # Find longest chain with height < hi
        left, right = 0, len(dp)
        while left < right:
            mid = (left + right) // 2
            if dp[mid][2] < hi:
                left = mid + 1
            else:
                right = mid

        if left > 0:
            max_len = dp[left - 1][0] + 1
            best_idx = dp[left - 1][1]
        else:
            max_len = 1
            best_idx = idx

        dp.append((max_len, best_idx, hi))

    # Find maximum chain
    max_len = 0
    best_idx = -1
    for length, last_idx, _ in dp:
        if length > max_len:
            max_len = length
            best_idx = last_idx

    # Reconstruct chain
    chain = []
    curr = best_idx
    for i in range(len(dp) - 1, -1, -1):
        if dp[i][1] == curr:
            chain.append(envelopes[i][2])
            curr = dp[i][0] - 1
            break

    while curr > 0:
        for i in range(len(dp) - 1, -1, -1):
            if dp[i][0] == curr and dp[i][2] < chain[-1]:
                chain.append(envelopes[i][2])
                curr -= 1
                break

    chain.reverse()
    print(max_len)
    print(' '.join(map(str, chain)))

