        if wi > w_card and hi > h_card:
            envelopes.append((wi, hi, i + 1))  # (width, height, 1-indexed index)

    if not envelopes:
        print(0)
        return

    # Sort by width, then by height
    envelopes.sort(key=lambda x: (x[0], x[1]))

    # dp: list of tuples (height, last_index, length)
    # This will store the longest chains ending with a given height
    dp = []

    for wi, hi, idx in envelopes:
        # Find the longest chain where we can append this envelope
        # We need height < hi
        left, right = 0, len(dp)
        while left < right:
            mid = (left + right) // 2
            if dp[mid][0] < hi:
                left = mid + 1
            else:
                right = mid

        if left > 0:
            new_len = dp[left - 1][2] + 1
            new_idx = dp[left - 1][1]
        else:
            new_len = 1
            new_idx = idx

        # If there's a chain with the same height, keep the one with the smallest index
        found = False
        for i, (h, iidx, l) in enumerate(dp):
            if h == hi:
                if iidx < new_idx:
                    # This chain has smaller index, we'll keep it and update our result
                    found = True
                    break
                else:
                    # This chain has larger index, we'll keep our new one
                    dp[i] = (hi, new_idx, new_len)
                    found = True
                    break

        if not found:
            dp.append((hi, new_idx, new_len))

    # Find the longest chain
    max_len = 0
    best_idx = -1
    for h, iidx, l in dp:
        if l > max_len:
            max_len = l
            best_idx = iidx

    # Reconstruct chain by backtracking
    chain = []
    curr_idx = best_idx
    curr_len = max_len

    # Find the last element with the given length
    for i in range(len(dp) - 1, -1, -1):
        if dp[i][2] == curr_len and dp[i][1] == curr_idx:
            chain.append(dp[i][1])
            curr_idx = None
            curr_len -= 1
            break

    while curr_len > 0:
        for i in range(len(dp) - 1, -1, -1):
            if dp[i][2] == curr_len:
                if curr_idx is None:
                    # We need the one with the largest height that is smaller than the previous
                    if dp[i][0] < chain[-1] and dp[i][1] < chain[-1]:
                        chain.append(dp[i][1])
                        curr_idx = dp[i][1]
                        curr_len -= 1
                        break
                else:
                    # We need the one that has a smaller height than the next one
                    if dp[i][0] < chain[-1] and dp[i][1] == curr_idx:
                        chain.append(dp[i][1])
                        curr_idx = dp[i][1]
                        curr_len -= 1
                        break

