def solve():
    MOD = 10**9 + 7
    N = int(input())

    from collections import defaultdict
    tree = defaultdict(list)
    for _ in range(N - 1):
        a, b = map(int, input().split())
        tree[a].append(b)
        tree[b].append(a)

    def count_valid_configurations(root):
        # DP: root is fixed
        # ways_even: path from root to leaf has even number of casinos
        # ways_odd: path from root to leaf has odd number of casinos

        def dp(u, parent):
            ways_even = 1  # No casino at u
            ways_odd = 1  # Casino at u

            for v in tree[u]:
                if v != parent:
                    even, odd = dp(v, u)

                    # Case 1: Don't put casino at u
                    ways_even = ways_even * even % MOD

                    # Case 2: Put casino at u
                    ways_odd = ways_odd * odd % MOD

            return (ways_even, ways_odd)

        return dp(root, -1)[0]  # Only even paths (path to root itself is just root, which has even count if no casino at root)

    # Try all possible roots
    answer = 0
    for root in range(1, N + 1):
        answer = (answer + count_valid_configurations(root)) % MOD

    print(answer)

solve()
