def solve():
    import sys
    input = sys.stdin.read().split()
    if not input:
        return

    data = list(map(int, input))
    if not data:
        return

    ptr = 0
    N = data[ptr]
    M = data[ptr+1]
    ptr += 2

    edges = []
    for _ in range(M):
        a = data[ptr]
        b = data[ptr+1]
        c = data[ptr+2]
        edges.append((a, b, c))
        ptr += 3

    # Build adjacency list
    from collections import defaultdict
    adj = defaultdict(list)

    for a, b, c in edges:
        adj[a].append((b, c))
        adj[b].append((a, c))

    # Assign values using BFS, starting with 0.5 to minimize absolute values
    values = [0.0] * (N + 1)  # 1-indexed
    visited = [False] * (N + 1)

    for start in range(1, N + 1):
        if not visited[start]:
            # BFS from start
            queue = [(start, True)]  # (node, is_start)
            visited[start] = True

            if N == 1:
                # Single node, we want to minimize absolute value
                values[start] = 0.0
            else:
                values[start] = 0.5
                queue.append((start, False))

            while queue:
                u, is_start = queue.pop(0)
                if not is_start:
                    for v, color in adj[u]:
                        if not visited[v]:
                            visited[v] = True
                            if color == 1:  # black edge
                                values[v] = 1.0 - values[u]
                            else:  # red edge
                                values[v] = 2.0 - values[u]
