    idx = 0
    n = int(data[idx])
    idx += 1
    k = int(data[idx])
    idx += 1

    u = []
    for _ in range(n):
        row = [int(data[idx + j]) for j in range(n)]
        idx += n
        u.append(row)
    return n, k, u

def compute_unfamiliar_value(u, start, end):
    """Compute unfamiliar value for contiguous group from start to end (inclusive)"""
    n = len(u)
    unfamiliar = 0
    for i in range(start, end + 1):
        for j in range(i + 1, end + 1):
            unfamiliar += u[i][j]
    return unfamiliar

def solve(n, k, u):
    # Precompute unfamiliar values for all contiguous subarrays
    # We'll use a 2D array where unfamiliar[i][j] is the unfamiliar value for the group from position i to j
    unfamiliar = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(i, n + 1):
            unfamiliar[i][j] = compute_unfamiliar_value(u, i - 1, j - 1)

    # DP: dp[i][j] = minimum unfamiliar value when we have i people left and j gondolas left
    INF = float('inf')
    dp = [[INF] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(n + 1):
        for j in range(k + 1):
            if dp[i][j] == INF:
                continue

            # Try putting m people into the next gondola
            for m in range(1, i + 1):
                # We have i people left, put m into this gondola
                # Then we have i - m people left and j - 1 gondolas left
                if j == k:
                    # If this is the last gondola, we need to put all remaining people
                    if m != i:
                        continue

                new_unfamiliar = dp[i][j] + unfamiliar[i - m + 1][i]
                if dp[i - m][j - 1] > new_unfamiliar:
                    dp[i - m][j - 1] = new_unfamiliar

    return dp[n][k]

if __name__ == "__main__":
