def solve():
    import sys
    input = sys.stdin.read().split()
    data = list(map(int, input))
    idx = 0
    t = data[idx]
    idx += 1

    result = []

    for _ in range(t):
        n = data[idx]
        idx += 1
        next_ = [0] * n
        for i in range(n):
            next_[i] = data[idx]
            idx += 1

        # Try to construct the permutation
        p = [0] * n

        # We'll try to place numbers from largest to smallest
        # Use a greedy approach
        available = list(range(1, n + 1))

        for i in range(n - 1, -1, -1):
            if next_[i] == -1:
                # next[i] is lost, place largest available
                p[i] = available.pop()
            else:
                # next[i] is given
                if next_[i] == n + 1:
                    # no next element, we're the largest
                    p[i] = available.pop()
                else:
                    # We need p[next[i]] > p[i]
                    # Also, all elements between i and next[i] must be <= p[i]
                    # Let's place the smallest available at next[i] to maximize flexibility
                    smallest_at_next = available.pop()

                    if not available:
                        result.append(-1)
                        break

                    # Now place largest available that's less than smallest_at_next
                    # at position i
                    for num in reversed(available):
                        if num < smallest_at_next:
                            p[i] = num
                            available.remove(num)
                            break
                    else:
                        # No such number found
                        result.append(-1)
                        break
        else:
            # Check if we can verify the solution
            valid = True
            for i in range(n):
