import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    x = list(map(int, data[1:n+1]))
    y = list(map(int, data[n+1:2*n+1]))

    # If all x are zero but not all y are zero, impossible
    if all(xi == 0 for xi in x):
        if all(yi == 0 for yi in y):
            print(0)
        else:
            print(-1)
        return

    # If all y are zero, we need to set all to zero
    if all(yi == 0 for yi in y):
        print(len(x))
        for i in range(n):
            print(f"{i+1} {i+1}")
        return

    # Otherwise, we need to achieve specific values
    # We can do: for each i, if x[i] != y[i], XOR x[i] with x[0] (or any non-zero element)
    # And if that doesn't work, we can XOR with something else

    # Let's try a better construction: if we have at least one non-zero, we can always achieve any configuration
    # We can do: for each i, if x[i] != y[i], XOR x[i] with x[0] (which might be non-zero)
    # This should work because we can always reset to 0.

