import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    s = next(it)

    removed = [False] * n

    for _ in range(m):
        l = int(next(it)) - 1  # Convert to 0-indexed
        r = int(next(it)) - 1
        c = next(it)

        # For each character c in the current string, check if it's in range l-r
        # Count how many characters are NOT removed before each position
        # This is O(n^2), but n is up to 2e5 so we need optimization
        # Let's optimize by just iterating through original positions

        for i in range(n):
            if s[i] == c:
                # Count how many characters before i are NOT removed
                cnt = 0
                for j in range(i):
                    if not removed[j]:
                        cnt += 1
                if l <= cnt <= r:
                    removed[i] = True

    result = ''.join(s[i] for i in range(n) if not removed[i])
    print(result)

if __name__ == "__main__":
    solve()
