# Build adjacency list
adj = [[] for _ in range(n + 1)]
for _ in range(m):
    v, u, w = map(int, input().split())
    adj[v].append((u, w))
    adj[u].append((v, w))

# Dijkstra's algorithm
import heapq

INF = float('inf')

dist = [[INF] * 51 for _ in range(n + 1)]  # last edge weight can be up to 50

dist[1][0] = 0  # starting at city 1 with no last edge

pq = [(0, 1, 0)]  # (cost, city, last_edge_weight)

while pq:
    cost, city, w = heapq.heappop(pq)

    if dist[city][w] < cost:
        continue

    # If we're at city 1, we can go to any neighbor with cost w^2
    if city == 1:
        for neighbor, weight in adj[city]:
            new_cost = weight * weight
            if dist[neighbor][weight] > new_cost:
                dist[neighbor][weight] = new_cost
                heapq.heappush(pq, (new_cost, neighbor, weight))
    else:
        # We can go to any neighbor with cost (w + weight)^2
        for neighbor, weight in adj[city]:
            new_cost = (w + weight) * (w + weight)
            if dist[neighbor][weight] > new_cost:
                dist[neighbor][weight] = new_cost
                heapq.heappush(pq, (new_cost, neighbor, weight))

# Output results
for t in range(1, n + 1):
    min_cost = min(dist[t][w] for w in range(51))
    if min_cost == INF:
        print(-1, end=' ')
    else:
        print(min_cost, end=' ')
