import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        m = int(next(it))

        a = []
        for _ in range(n):
            row = [int(next(it)) for _ in range(m)]
            a.append(row)

        # Create b using the checkerboard pattern
        b = []
        for i in range(n):
            new_row = []
            for j in range(m):
                if (i + j) % 2 == 0:
                    # Even (i+j): increment by 1
                    b_val = a[i][j] + 1
                else:
                    # Odd (i+j): keep as is
                    b_val = a[i][j]
                new_row.append(str(b_val))
            b.append(new_row)

        # Print the result
        for row in b:
            print(' '.join(row))

if __name__ == "__main__":
    solve()
