def solve():
    MOD = 10**6 + 3
    C, W, H = map(int, input().split())

    # dp[h][w] = number of ways to build a wall with exactly h columns and total width w
    dp = [[0] * (C + 1) for _ in range(H + 1)]
    dp[0][0] = 1  # Empty wall

    for h in range(H + 1):
        for w in range(C + 1):
            # For each number of columns
            # If we have h columns, we can add a new column with width 1..W
            if h > 0:
                for w_add in range(1, min(W, C - w) + 1):
                    dp[h][w + w_add] = (dp[h][w + w_add] + dp[h - 1][w]) % MOD

    # Sum all ways with up to H columns
    result = sum(dp[h][C] for h in range(H + 1)) % MOD
    print(result)

solve()
