def count_distinct_colorings(colors):
    from collections import Counter
    from math import factorial

    # Count occurrences of each color
    color_counts = Counter(colors)
    total = 0

    # Identity rotation (1 rotation)
    identity_colorings = factorial(6)
    for count in color_counts.values():
        identity_colorings //= factorial(count)
    total += identity_colorings

    # 90°/270° face rotations (6 rotations total)
    # For a coloring to be fixed: 4 faces of one color, 2 of another
    counts = list(color_counts.values())
    for i in range(6):
        for j in range(i+1, 6):
            count1 = counts[i]
            count2 = counts[j]
            if count1 == 4 and count2 == 2:
                # 4 faces of one color, 2 opposite faces of another
                # This fixes a specific arrangement
                total += 6  # 6 such rotations

    # 180° face rotations (3 rotations total)
    # For a coloring to be fixed: 2 pairs of opposite faces
    for count1 in counts:
        for count2 in counts:
            for count3 in counts:
                if sorted([count1, count2, count3]) == [2, 2, 2]:
                    # 3 pairs of opposite faces
                    total += 3  # 3 such rotations

    # 120°/240° vertex rotations (8 rotations total)
    # For a coloring to be fixed: 3 faces of one color, 3 of another
    for count1 in counts:
        for count2 in counts:
            for count3 in counts:
                if sorted([count1, count2, count3]) == [3, 3, 0]:
