    # 180° edge rotations (6 rotations total)
    # For a coloring to be fixed: 3 pairs of opposite faces
    for count1 in counts:
        for count2 in counts:
            for count3 in counts:
                if sorted([count1, count2, count3]) == [2, 2, 2]:
                    # 3 pairs of opposite faces
